// Mazmorras de Toba: the scepter, the form, the generation and the trial spawners.
// Generated by tools/mazmorras.py (the dungeon itself is built by gen.js).
import { BlockPermutation, BlockVolume, ItemStack, system, world } from "@minecraft/server";
import { ActionFormData, ModalFormData } from "@minecraft/server-ui";
import {
  buildDungeon, DIR_NAME, ENTRANCES, MAX_FLOORS, maxFloorsAt, MOB_FAMILIES, planDungeon, THEME_KEYS, THEMES, TYPE_NAME,
} from "./gen.js";

const CFG = __CONFIG__;
const TAG = "§2[Mazmorras]§r ";

// ------------------------------------------------------------ blocks
const perms = new Map();
function resolveOne(b) {
  try {
    return typeof b === "string" ? BlockPermutation.resolve(b) : BlockPermutation.resolve(b.id, b.states);
  } catch {
    return null;
  }
}
function perm(block) {
  const key = typeof block === "string" ? block : JSON.stringify(block);
  if (!perms.has(key)) {
    let p = resolveOne(block);
    if (!p && typeof block !== "string") {
      for (const alt of block.alt ?? []) if ((p = resolveOne(alt))) break;
      if (!p) p = resolveOne(block.id);
    }
    if (!p) console.warn(`[Mazmorras] bloque desconocido: ${key}`);
    perms.set(key, p);
  }
  return perms.get(key);
}

function apply(dim, op) {
  if (op[0] === "f") {
    const [, x1, y1, z1, x2, y2, z2, b] = op;
    const p = perm(b);
    if (!p) return;
    if (x1 === x2 && y1 === y2 && z1 === z2) dim.getBlock({ x: x1, y: y1, z: z1 })?.setPermutation(p);
    else dim.fillBlocks(new BlockVolume({ x: x1, y: y1, z: z1 }, { x: x2, y: y2, z: z2 }), p);
    return;
  }
  const [, x, y, z, b, items] = op;
  const p = perm(b);
  if (!p) return;
  const block = dim.getBlock({ x, y, z });
  if (!block) return;
  block.setPermutation(p);
  if (op[0] === "c") {
    const inv = block.getComponent("minecraft:inventory")?.container;
    if (!inv) return;
    for (const [id, count] of items) {
      try {
        inv.addItem(new ItemStack(id, count));
      } catch {}
    }
  }
}

function runOps(dim, ops, onStep) {
  return new Promise((resolve) => {
    system.runJob((function* () {
      let n = 0;
      for (const op of ops) {
        try {
          apply(dim, op);
        } catch {}
        if (++n % CFG.opsPerYield === 0) {
          onStep?.(CFG.opsPerYield);
          yield;
        }
      }
      onStep?.(n % CFG.opsPerYield);
      resolve();
    })());
  });
}

// ------------------------------------------------------------ loading the area
function isLoaded(dim, [x1, y1, z1, x2, , z2]) {
  for (let x = x1; x <= x2 + 15; x += 16)
    for (let z = z1; z <= z2 + 15; z += 16) {
      try {
        if (!dim.getBlock({ x: Math.min(x, x2), y: y1, z: Math.min(z, z2) })) return false;
      } catch {
        return false;
      }
    }
  return true;
}

let areaCounter = 0;
async function withLoaded(dim, box, work) {
  let name = null;
  if (!isLoaded(dim, box)) {
    name = `dng_${system.currentTick % 100000}_${areaCounter++}`;
    try {
      dim.runCommand(`tickingarea add ${box[0]} ${box[1]} ${box[2]} ${box[3]} ${box[1]} ${box[5]} ${name}`);
      world.setDynamicProperty("dng:area", name);
    } catch (e) {
      console.warn(`[Mazmorras] no se pudo crear la zona de carga: ${e}`);
      name = null;
    }
    for (let i = 0; i < 80 && !isLoaded(dim, box); i++) await system.waitTicks(5);
  }
  try {
    await work();
  } finally {
    if (name) {
      try {
        dim.runCommand(`tickingarea remove ${name}`);
      } catch {}
      world.setDynamicProperty("dng:area", undefined);
    }
  }
}

// Pieces close to each other are built together, with one loaded area each.
function tiles(pieces) {
  const map = new Map();
  for (const p of pieces) {
    const cx = Math.floor((p.box[0] + p.box[3]) / 2 / CFG.tile), cz = Math.floor((p.box[2] + p.box[5]) / 2 / CFG.tile);
    const k = `${cx},${cz}`;
    if (!map.has(k)) map.set(k, { pieces: [], box: [...p.box] });
    const t = map.get(k);
    t.pieces.push(p);
    for (let i = 0; i < 3; i++) t.box[i] = Math.min(t.box[i], p.box[i]);
    for (let i = 3; i < 6; i++) t.box[i] = Math.max(t.box[i], p.box[i]);
  }
  return [...map.values()];
}

// ------------------------------------------------------------ generation
let generating = null;

function facingOf(player) {
  const v = player.getViewDirection();
  if (Math.abs(v.x) > Math.abs(v.z)) return v.x > 0 ? 0 : 1;
  return v.z > 0 ? 2 : 3;
}

async function generate(player, opts) {
  const dim = player.dimension;
  const total = opts.built.pieces.reduce((a, p) => a + p.ops.length, 0);
  let done = 0, lastShown = -1;
  const show = () => {
    const pct = Math.floor((done / total) * 100);
    if (pct === lastShown) return;
    lastShown = pct;
    try {
      player.onScreenDisplay.setActionBar(`§2Generando mazmorra... §f${pct}%`);
    } catch {}
  };
  for (const phase of [0, 1, 2])
    for (const tile of tiles(opts.built.pieces.filter((p) => p.phase === phase)))
      await withLoaded(dim, tile.box, async () => {
        for (const piece of tile.pieces)
          await runOps(dim, piece.ops, (n) => {
            done += n;
            show();
          });
      });

  // the trial spawners start working once everything is built
  for (const s of opts.built.spawners) {
    const id = (world.getDynamicProperty("dng:next") ?? 0) + 1;
    world.setDynamicProperty("dng:next", id);
    const sp = {
      id, dim: dim.id, x: s.x, y: s.y, z: s.z, box: s.box, kind: s.kind, family: s.family, bonus: s.bonus ?? 0,
      state: "waiting", spawned: 0, players: 1, until: 0,
    };
    spawners.set(id, sp);
    save(sp);
  }
}

// ------------------------------------------------------------ the form
async function showForm(player, form) {
  for (let i = 0; i < 10; i++) {
    const res = await form.show(player);
    if (res.canceled && res.cancelationReason === "UserBusy") {
      await system.waitTicks(10);
      continue;
    }
    return res;
  }
  return { canceled: true };
}

async function openMenu(player) {
  const names = THEME_KEYS.map((k) => `${THEMES[k].name} §7(${THEMES[k].desc})`);
  const form = new ModalFormData()
    .title("Generador de Mazmorras")
    .dropdown("§2Mazmorra de toba y cuevas frondosas.§r\n\nTipo de mazmorra", names, { defaultValueIndex: 0 })
    .slider("Número de salas", CFG.minRooms, CFG.maxRooms, { valueStep: 1, defaultValue: CFG.defaultRooms })
    .slider("Pisos (como máximo)", 1, MAX_FLOORS, { valueStep: 1, defaultValue: 4 })
    .toggle("Salas de parkour", { defaultValue: true })
    .textField("Semilla (opcional)", "aleatoria");
  const res = await showForm(player, form);
  if (res.canceled || !res.formValues) return;
  const [ti, rooms, floorsWanted, parkour, seedText] = res.formValues;
  const loc = player.location;
  const origin = { x: Math.floor(loc.x), y: Math.floor(loc.y), z: Math.floor(loc.z) };
  const dim = player.dimension;
  const maxFloors = maxFloorsAt(origin.y, dim.heightRange.min);
  if (maxFloors < 1) {
    player.sendMessage(`${TAG}§cEstás demasiado abajo: sube un poco para generar la mazmorra.`);
    return;
  }
  if (origin.y + 10 >= dim.heightRange.max) {
    player.sendMessage(`${TAG}§cEstás demasiado arriba para generar la entrada.`);
    return;
  }
  const floors = Math.min(Number(floorsWanted), maxFloors);
  const text = String(seedText ?? "").trim();
  let seed = Number.parseInt(text, 10);
  if (!Number.isFinite(seed)) seed = text ? [...text].reduce((h, c) => (Math.imul(h, 31) + c.charCodeAt(0)) | 0, 7) : Math.floor(Math.random() * 2147483647);
  const facing = facingOf(player);
  const theme = THEME_KEYS[Number(ti)] ?? THEME_KEYS[0];
  const plan = planDungeon({ seed, theme, rooms: Number(rooms), floors, facing, parkour: !!parkour });
  const built = buildDungeon(plan, origin);
  const [x1, , z1, x2, , z2] = built.bounds;
  const counts = Object.entries(plan.counts).map(([t, n]) => `${n} de ${TYPE_NAME[t]}`).join(", ");

  const confirm = new ActionFormData()
    .title(THEMES[theme].name)
    .body(
      `§fSalas: §a${plan.rooms.length - 1}§f (${counts})\n` +
      (plan.rooms.length - 1 < Number(rooms) ? `§7(no cabían más salas: se pidieron ${rooms})\n` : "") +
      `§fPisos: §a${plan.floorsUsed}${floors < Number(floorsWanted) ? " §7(no caben más aquí)" : ""}\n` +
      `§fEntrada: §a${ENTRANCES[plan.tier - 1]}§f (dificultad ${plan.tier}/4)${plan.rare ? " §d¡mazmorra rara!" : ""}\n` +
      `§fSemilla: §7${seed}\n\n` +
      `§fLa entrada aparecerá §aaquí mismo§f y la mazmorra bajará hacia el §a${DIR_NAME[facing]}§f.\n` +
      `§fZona: unos §a${x2 - x1 + 1} x ${z2 - z1 + 1}§f bloques.\n\n` +
      "§cTodo lo que haya en esa zona bajo tierra será reemplazado.",
    )
    .button("§2Generar")
    .button("Cancelar");
  const res2 = await showForm(player, confirm);
  if (res2.canceled || res2.selection !== 0) return;
  if (generating) {
    player.sendMessage(`${TAG}§cYa se está generando otra mazmorra (${generating}). Espera a que termine.`);
    return;
  }
  generating = player.name;
  player.sendMessage(`${TAG}Generando §a${THEMES[theme].name}§r con ${rooms} salas...`);
  const t0 = Date.now();
  try {
    await generate(player, { built });
    player.onScreenDisplay.setTitle(`§2${THEMES[theme].name}`, {
      subtitle: "§7la mazmorra te espera bajo tus pies", fadeInDuration: 10, stayDuration: 50, fadeOutDuration: 20,
    });
    player.sendMessage(`${TAG}¡Lista! (${((Date.now() - t0) / 1000).toFixed(1)} s, ${built.spawners.length} generadores de prueba)`);
    player.playSound("random.levelup", { volume: 0.6 });
  } catch (e) {
    player.sendMessage(`${TAG}§cError generando la mazmorra: ${e}`);
    console.warn(`[Mazmorras] ${e}\n${e?.stack ?? ""}`);
  } finally {
    generating = null;
  }
}

const opening = new Set();
world.afterEvents.itemUse.subscribe(({ source: player, itemStack }) => {
  if (itemStack?.typeId !== CFG.item || player?.typeId !== "minecraft:player") return;
  if (opening.has(player.id)) return;
  opening.add(player.id);
  openMenu(player)
    .catch((e) => console.warn(`[Mazmorras] ${e}`))
    .finally(() => opening.delete(player.id));
});

// ------------------------------------------------------------ trial spawners
// The vanilla trial spawner only works with data that scripts cannot set, so the
// script runs them: a player comes close, mobs spawn in waves, and when they are all
// dead the spawner drops its reward and rests for a while.
const spawners = new Map();
const STATE = { waiting: 1, active: 2, eject: 4, cooldown: 5 };
const save = (sp) => world.setDynamicProperty(`dng:sp:${sp.id}`, JSON.stringify(sp));
const forget = (sp) => {
  spawners.delete(sp.id);
  world.setDynamicProperty(`dng:sp:${sp.id}`, undefined);
};

let started = false;
function start() {
  started = true;
  for (const id of world.getDynamicPropertyIds()) {
    if (!id.startsWith("dng:sp:")) continue;
    try {
      const sp = JSON.parse(world.getDynamicProperty(id));
      if (sp.state === "eject") sp.state = "cooldown"; // the world closed while it dropped the reward
      spawners.set(sp.id, sp);
    } catch {}
  }
  // a ticking area left behind by an interrupted generation
  const area = world.getDynamicProperty("dng:area");
  if (typeof area === "string")
    for (const d of ["overworld", "nether", "the_end"])
      try {
        world.getDimension(d).runCommand(`tickingarea remove ${area}`);
      } catch {}
  world.setDynamicProperty("dng:area", undefined);
}

function setState(block, n) {
  try {
    if (block.permutation.getState("trial_spawner_state") !== n)
      block.setPermutation(block.permutation.withState("trial_spawner_state", n));
  } catch {}
}

const centre = (sp) => ({ x: sp.x + 0.5, y: sp.y + 0.5, z: sp.z + 0.5 });
const tagOf = (sp) => `dng_sp_${sp.id}`;

function near(dim, sp, dist) {
  return dim.getPlayers({ location: centre(sp), maxDistance: dist })
    .filter((p) => Math.abs(p.location.y - sp.y) <= 4);
}

function isFree(dim, x, y, z) {
  try {
    const a = dim.getBlock({ x, y, z }), b = dim.getBlock({ x, y: y + 1, z }), g = dim.getBlock({ x, y: y - 1, z });
    return a?.isAir && b?.isAir && g && !g.isAir && !g.isLiquid;
  } catch {
    return false;
  }
}

function spawnOne(dim, sp) {
  const [x1, y1, z1, x2, , z2] = sp.box;
  const mobs = MOB_FAMILIES[sp.family] ?? MOB_FAMILIES.zombis;
  for (let i = 0; i < 16; i++) {
    const x = x1 + Math.floor(Math.random() * (x2 - x1 + 1)), z = z1 + Math.floor(Math.random() * (z2 - z1 + 1));
    if (x === sp.x && z === sp.z) continue;
    if (!isFree(dim, x, y1, z)) continue;
    const loc = { x: x + 0.5, y: y1, z: z + 0.5 };
    try {
      const e = dim.spawnEntity(mobs[Math.floor(Math.random() * mobs.length)], loc);
      e.addTag(tagOf(sp));
      dim.spawnParticle("minecraft:basic_flame_particle", { x: loc.x, y: loc.y + 0.5, z: loc.z });
      dim.spawnParticle("minecraft:basic_flame_particle", centre(sp));
      dim.playSound("trial_spawner.spawn_mob", loc, { volume: 0.8 });
      return true;
    } catch {}
  }
  return false;
}

function reward(dim, sp) {
  const table = sp.kind === "guardian" ? CFG.guardianRewards : CFG.rewards;
  const items = table.always.map(([id, n]) => [id, n]);
  for (let p = 0; p < sp.players; p++) {
    const pool = table.random.slice();
    for (let k = 0; k < table.rolls; k++) {
      const [id, lo, hi] = pool.splice(Math.floor(Math.random() * pool.length), 1)[0];
      items.push([id, lo + Math.floor(Math.random() * (hi - lo + 1))]);
    }
  }
  items.forEach(([id, n], i) =>
    system.runTimeout(() => {
      try {
        dim.spawnItem(new ItemStack(id, n), { x: sp.x + 0.5, y: sp.y + 1.3, z: sp.z + 0.5 });
        dim.playSound("trial_spawner.eject_item", centre(sp), { volume: 0.8 });
        dim.spawnParticle("minecraft:villager_happy", { x: sp.x + 0.5, y: sp.y + 1.2, z: sp.z + 0.5 });
      } catch {}
    }, 10 + i * 8));
  return 10 + items.length * 8;
}

function tickSpawner(sp) {
  const dim = world.getDimension(sp.dim);
  let block;
  try {
    block = dim.getBlock(sp);
  } catch {
    return; // not loaded
  }
  if (!block) return;
  if (block.typeId !== "minecraft:trial_spawner") return forget(sp);
  const now = system.currentTick;

  if (sp.state === "cooldown") {
    setState(block, STATE.cooldown);
    if (world.getAbsoluteTime() >= sp.until) {
      sp.state = "waiting";
      save(sp);
    }
    return;
  }
  if (sp.state === "eject") return setState(block, STATE.eject);
  if (sp.state === "waiting") {
    setState(block, STATE.waiting);
    const players = near(dim, sp, CFG.detect);
    if (!players.length) return;
    sp.state = "active";
    sp.players = Math.max(1, players.length);
    const guard = sp.kind === "guardian" ? 2 : 1;
    sp.total = (CFG.mobsBase + CFG.mobsPerPlayer * (sp.players - 1) + (sp.bonus ?? 0)) * guard;
    sp.simul = CFG.simulBase + (sp.players - 1) + (guard - 1);
    sp.spawned = 0;
    sp.lastSpawn = 0;
    sp.lastSeen = now;
    save(sp);
    setState(block, STATE.active);
    dim.playSound("trial_spawner.detect_player", centre(sp), { volume: 1 });
    return;
  }
  // active
  setState(block, STATE.active);
  const alive = dim.getEntities({ tags: [tagOf(sp)] });
  const players = near(dim, sp, CFG.leave);
  if (players.length) sp.lastSeen = now;
  else if (now - (sp.lastSeen ?? now) > CFG.abandonTicks) {
    // everybody left: the spawner goes back to sleep and takes its mobs
    for (const e of alive) e.remove();
    sp.state = "waiting";
    save(sp);
    return;
  }
  if (sp.spawned < sp.total && alive.length < sp.simul && now - (sp.lastSpawn ?? 0) >= CFG.spawnDelay) {
    if (spawnOne(dim, sp)) {
      sp.spawned++;
      sp.lastSpawn = now;
      save(sp);
    }
  }
  if (sp.spawned >= sp.total && !alive.length) {
    sp.state = "eject";
    save(sp);
    setState(block, STATE.eject);
    const ticks = reward(dim, sp);
    system.runTimeout(() => {
      sp.state = "cooldown";
      sp.until = world.getAbsoluteTime() + CFG.cooldownTicks;
      save(sp);
    }, ticks + 10);
  }
}

system.runInterval(() => {
  if (!started) start();
  for (const sp of spawners.values()) {
    try {
      tickSpawner(sp);
    } catch (e) {
      console.warn(`[Mazmorras] generador ${sp.id}: ${e}`);
    }
  }
}, 10);
